    <main className="demo-shell hardware-shell app-bottom-nav-shell">
      <header className="demo-header app-page-header">
        <h1>{t('navigation.sensors')}</h1>
      </header>
      <SensorSetupPage flow={flow} />
    </main>
  );
};
